        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = dp[i - 1][j];
      }
    }
  }

  bool found = dp[m][n];
  if (found) {
    print("Pattern found at positions: ${List.generate(n, (i) => i + 1)}");
  } else {
