int _calculateCombinations(int n, int k) {
  int total = 1;
  for (int i = 1; i <= n - k + 1; i++) {
    total *= i;
  }
  return total;
}

List<List<String>> _generateCombinations(List<String> items, int k) {
  if (k <= 0 || k > items.length) return [];

  final int n = items.length;
  final List<String> current = <String>[];
  final List<List<String>> result = <List<String>>[];

  for (int i = 0; i < k; i++) {
    current.add(items[i]);
  }
  result.add(current);

  for (int i = k; i < n; i++) {

    current.removeLast();
    current.add(items[i]);
    result.add(current);

    if (i < n - 1) {
      current.removeLast();
    }
  }

  return result;
}

