void fn0(List<String> args) {

  if (args.length != 2) {
    print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
    return;
  }

  final int k = int.tryParse(args[0]) ?? 0;
  final List<String> items = args[1].split(' ');

  if (k < 0 || k > items.length) {
    print('k must be between 0 and n (inclusive). n=${items.length}, k=$k');
    return;
  }

  final int n = items.length;
  final int totalCombinations = n! / k!;

  print('k=$k, items=$items, Total combinations: $totalCombinations');

  List<String> combinations = List.generate(totalCombinations, (i) => items.sublist(i * k, i * k + k));

  for (final combination in combinations) {
    print(combination);
  }
}

