    print('No args provided. Using default input: k=3, items=A,B,C,D');
    final k = 3;
    final items = ['A', 'B', 'C', 'D'];
  } else {

    final k = int.tryParse(args[0]) ?? 3;
    if (k <= 0) {
      print('First argument must be an integer k (size of combinations). Got: $k');
      return;
    }
    final n = args.length - 1;
    if (n < 0) {
      print('More arguments provided than k. k=$k, items=${args.sublist(1)}');
      return;
    }
    final items = args.sublist(1);
  }

  if (k > n) {
    print('k must be between 0 and n (inclusive). n=$n, k=$k');
    return;
  }

  final total = 1 << k; 
  print('Total combinations: $total');

  for (var mask = 0; mask < total; mask++) {
    final selected = <String>[];
    for (var i = 0; i < k; i++) {
      if ((mask & (1 << i)) != 0) {
        selected.add(items[i]);
      }
    }
    print(selected);
  }
}

