void fn0() {

  final rng = Random(0);
  const int width = 50;
  const int height = 30;
  final int userCount = 10;

  final data = <List<double>>List.generate(
    height,
    (_) => List.generate(width, (_) => rng.nextDouble()),
  );

  final clusters = List<List<int>>.generate(
    userCount,
    (_) => rng.nextInt(height, width).toList(),
  );

  final result = <String>[];
  for (var i = 0; i < userCount; i++) {
    final points = clusters[i].expand((x, y) => [x, y]).toList();
    final active = points.where((x, y) => data[y][x] >= 0.66).length;
    final regions = points.fold<Set<int>>({}, (s, p) => s.add(p));
    final uniqueCount = regions.length;

    result.add(
      'User $i: ${active.toString().padLeft(3)} / ${uniqueCount.toString().padLeft(3)} = ${(active / uniqueCount * 100).toStringAsFixed(1)}%',
    );
  }

  print('User Activity Heatmap (Day x Hour)');
  print('---------------------------------------------');
  for (var y = 0; y < height; y++) {
    for (var x = 0; x < width; x++) {
      final isWithin = clusters.every((p) => p.contains(x, y));
      final symbol = isWithin ? '#' : data[y][x] >= 0.66 ? '*' : '.';
      print(symbol + ' ');
    }
    print('');
  }
  print('\nLegend:');
  print('  "#" = high activity');
  print('  "*" = medium activity');
  print('  "." = low activity');
  print('  " " = no activity');
  print('');
  print(result.join('\n'));
}

