double fn0(int p0, int p1, int p2, int p3) {
  if (p2 <= 0 || p3 <= 0) {
    return 0.0;
  }
  int totalFloors = p0 + p1;
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }
  int g = p2;
  for (int i = 0; i < totalFloors; i++) {
    g = gcd(g, p3);
  }
  return g / (p2 * p3);
}

