    if (!order.containsKey(c)) continue;
    final rankIndex = ranks[c]!;
    final suitOrder = order[c]!;
    final suitKeys = ['Clubs', 'Diamonds', 'Hearts', 'Spades'];
    for (var j = 0; j < suitKeys.length; j++) {
      if (j == suitOrder) continue;
      final otherSuit = suitKeys[j];
      if (!suits.containsKey(otherSuit)) continue;
      final otherSuitVal = suits[otherSuit]!;
      if (rankIndex < otherSuitVal) {
        result[otherSuit] = result[otherSuit]! + (otherSuitVal - rankIndex);
      }
    }
  }
  return result;
}

