Map<String, int> fn0(List<int> arrivalDays, int mergeDay) {
  if (arrivalDays.length <= 1) {
    return {'pairCount': 0, 'mashupDuration': 0};
  }

  int getPairCount(int index, int currentDay, int lastMergeDay) {
    if (index >= arrivalDays.length) return 0;

    int arrival = arrivalDays[index];
