    if (gap >= 30) {
      return getPairCount(index + 1, currentDay, lastMergeDay);
    }

    if (gap <= 7 && currentDay >= lastMergeDay) {
      return getPairCount(index + 1, currentDay, lastMergeDay) + 1;
    }

    return getPairCount(index + 1, currentDay, lastMergeDay);
  }

  int getMashupDuration(int index, int currentDay, int lastMergeDay) {
    if (index >= arrivalDays.length) return 0;

    int arrival = arrivalDays[index];
