    if (gap <= 7 && currentDay >= lastMergeDay) {
      return gap + getMashupDuration(index + 1, currentDay, lastMergeDay);
    }

    return getMashupDuration(index + 1, currentDay, lastMergeDay);
  }

  int lastMerge = mergeDay;
  for (int i = 1; i < arrivalDays.length; i++) {
    if (arrivalDays[i] > arrivalDays[i - 1]) {
      lastMerge = arrivalDays[i] - 1;
    }
  }

  return {'pairCount': getPairCount(0, mergeDay, lastMerge), 'mashupDuration': getMashupDuration(0, mergeDay, lastMerge)};
