class Quaternion {
  final Complex w, x, y, z;

  const Quaternion(this.w, this.x, this.y, this.z);

  factory Quaternion(double w, double x, double y, double z) {
    return Quaternion(
      Complex(w, 0.0),
      Complex(x, 0.0),
      Complex(y, 0.0),
      Complex(z, 0.0),
    );
  }

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.fromList(List<double> parts) {
    return Quaternion(parts[0], parts[1], parts[2], parts[3]);
  }

  Complex conjugate() {
    return Complex(w, -x) + Complex(y, -z);
  }

  Complex inverse() {
    final c = conjugate();
    final d = w * w + x * x + y * y + z * z;
    return Complex(c.w / d, -(c.x * w + c.y * x + c.z * z) / d);
  }

  Quaternion normalized() {
    final c = conjugate();
    final d = w * w + x * x + y * y + z * z;
    return Quaternion(c.w / d, -(c.x * w + c.y * x + c.z * z) / d, 0.0, 0.0);
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      w + other.w,
      x + other.x,
      y + other.y,
      z + other.z,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      w - other.w,
      x - other.x,
      y - other.y,
      z - other.z,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      w * scalar,
      x * scalar,
      y * scalar,
      z * scalar,
    );
  }

  Quaternion operator *(Quaternion other) {
    final w = w * other.w - x * other.x - y * other.y - z * other.z;
    final x = w * other.x + x * other.w + y * other.z - z * other.y;
    final y = w * other.y + x * other.z + y * other.w - z * other.x;
    final z = w * z + x * other.y + y * other.x - x * other.z;
    return Quaternion(w, x, y, z);
  }

  double norm() {
    final d = w * w + x * x + y * y + z * z;
    return d.abs();
  }
}

