class Quaternion {

  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) {
    final double xx = x * x;
    final double yy = y * y;
    final double zz = z * z;
    final double ww = w * w;

    return Quaternion(
        xx * ww - yy * zz,
        2 * (xx * zz + yy * ww),
        xx * zz + yy * ww,
        xx * ww + yy * zz);
  }

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion inverse() {
    final double det = x * (w * w - z * z) - y * (x * z - w * w);
    if (det == 0.0) throw ArgumentError('Cannot invert zero quaternion');
    return Quaternion(
        (x * w - y * z) / det,
        (y * w - x * z) / det,
        (z * w - x * y) / det,
        (w * w - x * x - y * y - z * z) / det);
  }

  Quaternion normalized() {
    final double norm = x * x + y * y + z * z + w * w;
    if (norm == 0.0) throw ArgumentError('Cannot normalize zero quaternion');
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  double norm() => x * x + y * y + z * z + w * w;

  double angle(Quaternion other) {
    final double dot = x * other.x + y * other.y + z * other.z + w * other.w;
    final double otherNorm = other.x * other.x + other.y * other.y + other.z * other.z + other.w * other.w;
    if (otherNorm == 0.0) return 0.0;
    return dot / otherNorm;
  }

  @override
  String toString() =>
      '$x + ${y}i + ${z}j + ${w}k';
}

