class Quaternion {
  final double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  Quaternion conjugate() {
    return Quaternion(x, y, -z, w);
  }

  Quaternion normalized() {
    var n = norm();
    if (n == 0) return Quaternion(0, 0, 0, 0);
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion inverse() {
    var n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(
        x / n, y / n, z / n, w / n) * conjugate();
  }

  double angle() {
    var a = x * x + y * y + z * z;
    var b = w * w;
    return math.atan2(math.sqrt(a), math.sqrt(b));
  }

  Quaternion rotateAxis(Quaternion axis) {
    var e = Quaternion(0, 0, 0, 1);
    return e + axis * 2 * angle() - 
        (axis * axis) * angle() * 2;
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

