class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  double get norm => x * x + y * y + z * z + w * w;

  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(Quaternion other) {
    final double xx = x * x;
    final double yy = y * y;
    final double zz = z * z;
    return Quaternion(
      2 * (xx * other.w + yy * other.z + zz * other.x) + x * other.x + y * other.y + z * other.z,
      2 * (xx * other.z + yy * other.w + zz * other.y) + y * other.y + z * other.z + w * other.x,
      2 * (zz * other.w + xx * other.y + yy * other.z) + z * other.z + x * other.x + y * other.y,
      2 * (xx * other.x + yy * other.y + zz * other.z) + x * other.x + y * other.y + z * other.z,
    );
  }

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion inverse() => this * conjugate();

  Quaternion normalized() {
    final double n = norm;
    return n == 0 ? Quaternion(0.0, 0.0, 0.0, 0.0) : 1 / n * this;
  }

  double angle(Quaternion other) {
    final double dot = x * other.x + y * other.y + z * other.z + w * other.w;
    final double otherNorm = other.norm;
    return dot > EPSILON ? (dot / otherNorm) * acos(dot / otherNorm) : 0.0;
  }

  Quaternion rotateZ(double angle) {
    final double c = cos(angle / 2.0);
    final double s = sin(angle / 2.0);
    return Quaternion(
      x * c - y * s,
      y * c + x * s,
      z,
      w,
    );
  }

  @override
  String toString() => 'Quaternion($x, $y, $z, $w)';
}

