    final q = Quaternion(0.0, 0.0, 0.0, 0.0);
    final s = sin(angle / 2.0);
    q.x = axis.x * s;
    q.y = axis.y * s;
    q.z = axis.z * s;
    q.w = cos(angle / 2.0);
    return q;
  }

