    return 0.0;
  }
  double calculate(int start, int end) {
    if (start >= end) {
      return 0.0;
    }
    final int mid = start + (end - start) ~/ 2;
    final int left = calculate(start, mid);
    final int right = calculate(mid + 1, end);
    final int total = sortedDistances[mid] * (mid + 1) + sortedDistances[end] * (end - mid);
    return left + right + total;
  }
  return calculate(0, sortedDistances.length - 1);
}

