Map<String, int> fn0(List<int> weights, int capacity) {
  if (weights.isEmpty) return {};
  if (capacity <= 0) return {"": 0};

  int n = weights.length;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    dp[i] = dp[i - 1];
    int currentWeight = weights[i - 1];
    if (currentWeight > capacity) {
      int maxUntil = dp[i - 1 - (currentWeight - capacity)];
      dp[i] = dp[i] > maxUntil ? dp[i] : maxUntil;
    }
  }

  Map<String, int> result = {};
  int maxCount = dp[n];
  for (int i = n; i > 0 && maxCount > 0; i--) {
    int currentWeight = weights[i - 1];
    if (currentWeight > capacity) {
      int maxUntil = dp[i - 1 - (currentWeight - capacity)];
      if (dp[i] != maxUntil) {
        result["${i - 1}"] = maxCount - 1;
      }
    }
    maxCount--;
  }
  return result;
}

