      for (int k = j; k >= w1; k--) {
        if (dp[i][k] != -1) {
          int cost = w1 + w2;
          if (dp[i][k] + cost <= dp[i + 1][j]) {
            dp[i + 1][j] = dp[i][k] + cost;
          }
        }
      }
    }
  }

  Map<String, int> result = {};
  int minCost = capacity + 1;
  for (int j = 0; j <= capacity; j++) {
    if (dp[weights.length - 2][j] != -1 && dp[weights.length - 2][j] + weights[weights.length - 1] <= minCost) {
      minCost = dp[weights.length - 2][j] + weights[weights.length - 1];
      result[minCost.toString()] = 1;
    }
  }
