List<String> fn0(List<String> entries) {
  List<String> result = [];
  List<String> history = [];
  List<int> stack = [];
  List<List<String>> historyStack = [];

  for (String entry in entries) {
    if (entry == 'OPEN') {
      history.add('OPEN');
      stack.add(0);
      historyStack.add([]);
    } else if (entry.startsWith('D:')) {
      String amountStr = entry.substring(2);
      int amount = int.parse(amountStr);
      int last = stack.removeLast();
      int newTotal = last + amount;
      stack.add(newTotal);
      history.add('D:$amount');
      historyStack.removeLast();
      historyStack.add(List.generate(history.length, (i) => history[i]));
    } else if (entry == 'C:') {
      history.add('CLOSE');
      stack.add(0);
      historyStack.add([]);
    } else if (entry == '!') {
      if (historyStack.isNotEmpty) {
        List<String> lastHistory = historyStack.removeLast();
        String action = lastHistory[lastHistory.length - 1];
        if (action == 'OPEN') {
          stack.removeLast();
        } else if (action == 'D:') {
          int amt = int.parse(action.substring(2));
          stack.add(stack.last - amt);
        } else if (action == 'CLOSE') {
          stack.removeLast();
        }
        history.add(action);
      }
    } else if (entry == 'FINAL:') {
      result.add('FINAL:${stack.last},result=${stack.length}');
    }
  }
  return result;
}

