      history.add('C:${qty}');
    } else {
      history.add(event);
    }
    ledger.add('FINAL:$net,result=${net.toString().padLeft(3, '0')}'
        '${history.isEmpty ? '' : '!' + history.join(' ')}');
    history.clear();
  }
