    if (arr[i] > maxVal) maxVal = arr[i];
  }

  void countSort(List<int> arr, int exp) {
    int n = arr.length;
    List<int> output = List.filled(n, 0); 
    List<int> count = List.filled(10, 0);

    for (int i = 0; i < n; i++) {
      int digit = (arr[i] ~/ exp) % 10;
      count[digit]++;
    }

    for (int i = 1; i < 10; i++) {
      count[i] += count[i - 1];
    }

    for (int i = n - 1; i >= 0; i--) {
      int digit = (arr[i] ~/ exp) % 10;
      output[count[digit] - 1] = arr[i];
      count[digit]--;
    }

    for (int i = 0; i < n; i++) {
      arr[i] = output[i];
    }
  }

  int exp = 1;
  while (maxVal ~/ exp > 0) {
    countSort(arr, exp);
    exp *= 10;
  }

  print('Sorted array: $arr');
}

