int kmpSearch(String text, String pattern) {
  if (pattern.isEmpty) return -1;
  if (text.isEmpty) return -1;

  List<int> lps = List.filled(patternLength, 0);
  int i = 0;
  int len = 1;

  while (i < textLength) {
    if (pattern[len] == text[i]) {
      i++;
      len++;
    }
    if (len == patternLength) {
      return i - len; 
    }
    else if (i < textLength && pattern[len] != text[i]) {
      if (len != 0) {
        len = lps[len - 1];
      } else {
        i++;
      }
    }
  }

  return -1;
}

