      x = x + (x >> 16);
      return x & 0x3F;
    }

    if (popcount(bytes) >= 12) {
      return 'big-endian';
    } else {
      return 'little-endian';
    }
  }

  int bytesAsInt(List<int> bytes) {
    int x = 0, i = 0;
    while (i < 4) {
      x = (x << 8) | (bytes[i] & 0xFF);
      i++;
    }
    return x;
  }

  List<int> toInts(List<int> bytes) {
    return bytes.map((b) => b & 0xFF).toList();
  }

  List<int> toBEInts(List<int> bytes) {
    return bytes.map((b) => (b << 8) | (b >> 8)).toList();
  }

  List<int> toLEInts(List<int> bytes) {
    return bytes.map((b) => (b >> 8) | ((b & 0xFF) << 8)).toList();
  }

  List<int> bytesLE = toLEInts(value.toRadixString(16).padLeft(16, '0').codeUnits);
  List<int> bytesBE = toBEInts(value.toRadixString(16).padLeft(16, '0').codeUnits);

  print('Host system is ${getByteOrder(value)}');
  print('Value from little-endian bytes: 0x${bytesLE.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');
  print('Value from big-endian bytes: 0x${bytesBE.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');

  int bytes2 = bytesAsInt(bytesBE);
  int bytes3 = bytesAsInt(bytesLE);

  print('Swapped from little to big: ${bytes3.toRadixString(16).padLeft(16, '0')}');
  print('Big-endian bytes: ${bytesBE.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');
  print('Little-endian bytes: ${bytesLE.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');
}

