class Role {
  String name;
  List<String> permissions;
  Role(this.name, this.permissions);
}

class Resource {
  String name;
  bool accessible;
  Resource(this.name, [this.accessible = true]);
}

class User {
  String name;
  List<String> roles;
  User(this.name, [this.roles = const []]);
}

class AccessControlSystem {
  Map<String, List<String>> resourceAccessMatrix = {};
  Map<String, Map<String, List<String>>> userRoles = {};
  Map<String, List<String>> auditLog = {};

  void grantRole(String user, String roleName) {
    if (!userRoles.containsKey(user)) {
      userRoles[user] = {};
    }
    userRoles[user]![roleName] = [];
  }

  void revokeRole(String user, String roleName) {
    if (userRoles.containsKey(user)) {
      if (userRoles[user]!.containsKey(roleName)) {
        userRoles[user]!.remove(roleName);
      }
    }
  }

  void grantPermission(String user, String resource, String action) {
    if (!resourceAccessMatrix.containsKey(resource)) {
      return;
    }
    Map<String, List<String>> resourceRoles = resourceAccessMatrix[resource]!;
    if (action == 'grant') {
      if (userRoles.containsKey(user)) {
        for (String role in userRoles[user]!.values) {
          if (!role.contains(resource)) {
            role.add(resource);
          }
        }
      }
    } else if (action == 'revoke') {
      for (String role in userRoles[user]!.values) {
        if (role.contains(resource)) {
          role.remove(resource);
        }
      }
    } else {
      print('  ❌  Unknown action: $action');
    }
  }

  bool checkAccess(String user, String resource, String action) {
    if (!resourceAccessMatrix.containsKey(resource)) {
      print('  ❌  Resource "${resource}" not found\n');
      return false;
    }
    Map<String, List<String>> resourceRoles = resourceAccessMatrix[resource]!;
    return resourceRoles.values.any((role) => userRoles.containsKey(user) && userRoles[user]!.contains(role));
  }

  void logAccess(String user, String resource, String action, String outcome) {
    String timestamp = DateTime.now().toLocal().toString();
    String entry = '$user: $action on $resource: $outcome';
    auditLog[timestamp] = (auditLog[timestamp] ?? <String>[])..add(entry);
  }

  void printResourceAccessMatrix() {
    print('=== Resource Access Matrix ===\n');
    for (var entry in resourceAccessMatrix.entries) {
      print('${entry.key}: ${entry.value.map((r) => r.padLeft(5)).join(', ')}');
    }
    print('');
  }

  void printUserPermissions(String user) {
    print('User: $user');
    print('Permissions: ${userRoles[user]!.values.join(', ')}\n');
  }

  void printAuditLog() {
    print('=== Audit Log ===\n');
    for (var entry in auditLog.entries.reversed) {
      print(entry.key);
      for (var line in entry.value) {
        print('  $line');
      }
    }
  }
}

