import 'dart:async';
import 'dart:convert';
class Role {
  final String name;
  final List<String> permissions;

  Role(this.name, this.permissions);

  @override
  String toString() => '$name: $permissions';
}

class Resource {
  final String name;
  final String type;
  final String? sensitiveData; 

  Resource(this.name, this.type, [this.sensitiveData]);

  @override
  String toString() => '$name ($type)';
}

class User {
  final String name;
  final Map<Resource, List<String>> permissions = {};

  User(this.name);

  void grant(Resource resource, [List<String> permissions = const []]) {
    permissions[resource] = permissions[resource] ?? [];
    permissions[resource]!.addAll(permissions);
  }

  void revoke(Resource resource, [List<String> permissions = const []]) {
    if (permissions.containsKey(resource)) {
      permissions[resource]!.removeWhere((p) => !permissions.contains(p));
    }
  }

  void displayPermissions() {
    print('Permissions:');
    permissions.forEach((resource, p) {
      if (p.isNotEmpty) {
        print('  - ${resource.type}: ${p.join(', ')}');
      } else {
        print('  - ${resource.type}: read');
      }
    });
  }
}

