import 'dart:async';
import 'dart:convert';
class Role {
  final String name;
  final List<String> permissions;

  Role(this.name, this.permissions);

  @override
  String toString() => '$name: $permissions';
}

class Resource {
  final String name;

  Resource(this.name);
}

class AccessControl {
  final Map<String, List<String>> userResources;
  final Map<String, List<String>> rolesResources;

  AccessControl(this.userResources, this.rolesResources);

  bool _hasAccess(String user, String resource, String role) {
    if (!userResources.containsKey(user)) {
      return false;
    }
    if (!rolesResources.containsKey(role)) {
      return false;
    }
    return userResources[user]!.contains(resource) ||
        rolesResources[role]!.contains(resource);
  }

  bool _attemptAccess(String user, String resource, String role) {
    if (!_hasAccess(user, resource, role)) {
      return false;
    }
    print('  ✓ Access GRANTED (Role: $role)');
    return true;
  }

  void denyAccess(String user, String resource) {
    print('  ✗ Access DENIED (${user} attempts to $resource)');
  }
}

