  }
  final permissions = roles[user]!;
  if (!permissions.contains(resource)) {
    print('  ✗ Access denied');
    return false;
  }
  print('  ✓ Access granted (Role: ${permissions.join(', ')})');
  return true;
}

void addRole(String user, String role) {
  if (!roles.containsKey(user)) {
    roles[user] = <String>[];
  }
  roles[user]!.add(role);
  print('  ➜ New role for $user: $role');
}

