import 'dart:async';
import 'dart:convert';
class Role {
  final String name;
  final List<String> permissions;
  Role(this.name, this.permissions);
}

class User {
  final String username;
  final Map<Role, Set<String>> roles;
  User(this.username, this.roles);

  void grantRole(String roleName) {
    roles[Role.name] = roles[Role.name] ?? {};
    roles[Role.name]!.add(roleName);
  }

  void removeRole(String roleName) {
    roles[Role.name] = roles[Role.name]
        ?.where((p) => p != roleName)
        ?.toSet() ?? {};
  }

  bool hasRole(String roleName) {
    return roles.containsKey(roleName) &&
        roles[roleName]!.contains(username);
  }
}

class Resource {
  final String name;
  final List<String> sensitiveData;
  Resource(this.name, [this.sensitiveData = const []]);
}

