void NetworkByteOrderExample() {

  const int value = 0x12345678;

  List<int> bytesLE = [0, 0, 0, 0];
  bytesLE[0] = value & 0xFF;
  bytesLE[1] = (value >> 8) & 0xFF;
  bytesLE[2] = (value >> 16) & 0xFF;
  bytesLE[3] = (value >> 24) & 0xFF;

  List<int> bytesBE = [0, 0, 0, 0];
  bytesBE[0] = value & 0xFF;
  bytesBE[1] = (value >> 8) & 0xFF;
  bytesBE[2] = (value >> 16) & 0xFF;
  bytesBE[3] = (value >> 24) & 0xFF;

  print('Network Byte Order Example:');
  print('Original value: 0x${value.toRadixString(16).toUpperCase().padLeft(8, '0')}' + '/0');
  print('As Little Endian bytes: [${bytesLE[0]}, ${bytesLE[1]}, ${bytesLE[2]}, ${bytesLE[3]}]');
  print('Back to host: ${bytesLE.map((b) => b.toRadixString(16).toUpperCase().padLeft(2, '0')).join(', ')}');

  print('---');

  print('As Big Endian bytes: [${bytesBE[0]}, ${bytesBE[1]}, ${bytesBE[2]}, ${bytesBE[3]}]');
  print('From bytes: 0x${bytesBE[0].toRadixString(16).toUpperCase().padLeft(2, '0')}, 0x${bytesBE[1].toRadixString(16).toUpperCase().padLeft(2, '0')}, 0x${bytesBE[2].toRadixString(16).toUpperCase().padLeft(2, '0')}, 0x${bytesBE[3].toRadixString(16).toUpperCase().padLeft(2, '0')}' + '/0');
}

