  const int valueLE = 0xLE01234567;
  const int valueBE = 0x78563412;

  const double floatValue = 3.14159;

  int bytesLE(int value) {

    int bytes = 0;
    int v = value;
    do {
      bytes++;
      v >>= 16;
    } while (v != 0);
    return bytes;
  }

  int swapBytesLE(int value) {
    int bytes = bytesLE(value);
    List<int> parts = List.filled(bytes, 0);
    for (int i = 0; i < bytes; i++) {
      parts[i] = (value >> (i * 16)) & 0xFFFF;
    }
    int result = 0;
    for (int i = 0; i < bytes; i++) {
      result |= (parts[i] << (i * 16));
    }
    return result;
  }

  int toLEBytes(int value) {
    List<int> parts = List.filled(bytesLE(value), 0);
    for (int i = 0; i < bytesLE(value); i++) {
      parts[i] = (value >> (i * 16)) & 0xFFFF;
    }
    return parts.join();
  }

  String bytesToHex(int value) {
    return List.generate(bytesLE(value), (i) => value.toRadixString(16).toUpperCase().padLeft(2, '0'))
        .join(' ');
  }

  List<int> fromBytesLE(String bytes) {
    if (bytes.isEmpty) return [];
    List<int> result = [];
    List<String> parts = bytes.split(' ');
    for (String part in parts) {
      if (part.length != 2) continue;
      int value = 0;
      for (int i = 0; i < 2; i++) {
        value = (value << 4) | part.codeUnitAt(i) - 48;
      }
      result.add(value);
    }
    return result;
  }

  int bytesToFloatLE(String bytes) {
    if (bytes.isEmpty) return 0;
    List<int> parts = fromBytesLE(bytes);
    int value = 0;
    for (int i = 0; i < 3; i++) {
      value = (value << 16) | parts[i];
    }
    value = (value << 16) | parts[3];
    return value;
  }

