    for (int i = 0; i < bytesLE(value); i++) {
      parts[i] = (value >> (i * 16)) & 0xFFFF;
    }
    return parts.map((part) => part.toRadixString(16).toUpperCase().padLeft(2, '0'))
        .join(' ');
  }

