  void generateRules(List<String> itemset, List<String> otherItems, double confidence) {
    if (otherItems.isEmpty) {
      String rule = itemset.join(' -> ');
      double support = itemCounts[itemset.join(' | ')]! / totalTransactions;
      print('$rule (support: $support, confidence: ${support * confidence})');
