      double newConfidence = (itemCounts[otherItem]! / itemCounts[newItemset.join(' | ')])! * confidence;

      if (newSupport >= minSupport && newConfidence >= minConfidence) {

        List<String> newOtherItems = List<String>.from(otherItems);
        newOtherItems.remove(otherItem);

        generateRules(newItemset, newOtherItems, newConfidence);
      }
