Map<String, int> fn0(List<int> weights, int targetSum) {
  int n = weights.length;
  if (n == 0) return {"size": 0, "index": -1};

  List<int> prefix = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + weights[i];
  }

  int lo = 0;
  int hi = n;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    if (prefix[mid] < targetSum) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }

  int count = lo;
  int sum = prefix[lo];
  int index = lo;
  while (sum > targetSum) {
    sum -= weights[index - 1];
    count--;
    index--;
  }

  return {"size": count, "index": index};
}

