Set<int> fn0(String board) {
  if (board.isEmpty) return <int>{};
  final FileSet fileSet = FileSet(board);
  final int cols = board.length;
  final Set<int> positions = <int>{};
  for (int i = 0; i < fileSet.files.length; i++) {
    for (int j = 0; j < cols; j++) {
      if (fileSet.files[i] == j && !fileSet.isBlocked(i, j)) {
        positions.add(i * cols + j);
      }
    }
  }
  return positions;
}

class FileSet {
  final String board;
  final List<int> files = <int>[];
  final List<int> blocked = <int>[];

  FileSet(this.board) {
    for (int i = 0; i < board.length; i++) {
      if (board[i] != '.') {
        files.add(i);
        blocked.add(1);
      } else {
        blocked.add(0);
      }
    }
  }

  bool isBlocked(int f, int c) {
    int idx = f * board.length + c;
    int count = 0;
    while (idx > 0) {
      count += blocked[idx - 1];
      idx -= 1;
    }
    return count > 0;
  }

  bool contains(int pos) {
    int file = pos ~/ board.length;
    int rank = pos % board.length;
    return isBlocked(file, rank);
  }

  bool containsAny(int f) {
    for (int i = 0; i < board.length; i++) {
      if (isBlocked(f, i)) return true;
    }
    return false;
  }

  bool containsAll(Set<int> positions) {
    for (var pos in positions) {
      if (!contains(pos)) return false;
    }
    return true;
  }

  bool containsAnyDiagonal() {
    for (int i = 0; i < board.length; i++) {
      for (int j = 0; j < board.length; j++) {
        if (i != j && isBlocked(i, j)) return true;
      }
    }
    return false;
  }

  bool containsAllDiagonals() {
    for (int i = 0; i < board.length; i++) {
      if (containsAnyDiagonal()) return true;
    }
    return false;
  }

  bool containsNoBlockers() {
    for (int f in files) {
      if (containsAny(f)) return false;
    }
    return true;
  }

  bool containsNoDiagonals() {
    return containsNoBlockers() && !containsAnyDiagonal();
  }
}

