class Rectangle {
  final double x;
  final double y;
  final double width;
  final double height;

  Rectangle(
      {required this.x,
      required this.y,
      required this.width,
      required this.height});

  Rectangle.square(double side)
      : this(x: side / 2, y: side / 2, width: side, height: side);

  Rectangle.fromPoints(Point p1, Point p2)
      : this(
          x: p1.x < p2.x ? p1.x : p2.x,
          y: p1.y < p2.y ? p1.y : p2.y,
          width: (p1.x - p2.x).abs(),
          height: (p1.y - p2.y).abs(),
        );

  Rectangle.centered(double centerX, double centerY, double radius)
      : this(
          x: centerX - radius,
          y: centerY - radius,
          width: 2 * radius,
          height: 2 * radius,
        );

  Rectangle.fromCenter(double centerX, double centerY, double width, double height)
      : this(
          x: centerX - width / 2,
          y: centerY - height / 2,
          width: width,
          height: height,
        );

  Rectangle.fromCenterXY(double centerX, double centerY, double size)
      : this(
          x: centerX - size / 2,
          y: centerY - size / 2,
          width: size,
          height: size,
        );

  Rectangle.withSides(double side1, double side2)
      : this(x: 0, y: 0, width: side1, height: side2);

  Rectangle.withCenters(
      Point p1, Point p2, double overlap) =>
        this(
          x: p1.x < p2.x ? p1.x : p2.x,
          y: p1.y < p2.y ? p1.y : p2.y,
          width: overlap,
          height: overlap,
        );

  Rectangle.withCentersXY(
      double centerX1,
      double centerY1,
      double centerX2,
      double centerY2,
      double overlap) =>
        this(
          x: centerX1 - overlap / 2,
          y: centerY1 - overlap / 2,
          width: overlap,
          height: overlap,
        );

  Rectangle get bounds => Rectangle.centered(x, y, width / 2, height / 2);

  Rectangle get union =>
      Rectangle.centered(x, y, width + overlap, height + overlap);

  Rectangle get intersection;

  Rectangle get right => Rectangle.centered(x + width, y, width, height);

  Rectangle get left => Rectangle.centered(x, y, width, height);

  Rectangle get bottom => Rectangle.centered(x, y + height, width, height);

  Rectangle get top => Rectangle.centered(x, y, width, height);

  Rectangle get center => Rectangle.square(width / 2);

  Rectangle get half => Rectangle.centered(x + width / 2, y + height / 2, width / 2, height / 2);

  bool contains(Point p) {
    return x < p.x && p.x < x + width &&
        y < p.y && p.y < y + height;
  }

  bool overlaps(Rectangle other) {
    return !(
        other.x > x + width ||
        x > other.x + other.width ||
        other.y > y + height ||
        y > other.y + other.height);
  }

  bool isDisjoint(Rectangle other) {
    return !(
        other.contains(Point(x, y)) ||
        contains(Point(other.x, other.y)) ||
        contains(Point(other.x + other.width, other.y)) ||
        contains(Point(x + width, other.y + height)));
  }

  bool isUnionDisjoint(Rectangle other) {
    return !overlaps(other);
  }

  bool touches(Rectangle other) {
    return overlaps(other) && !isDisjoint(other);
  }

  bool isParallel(Rectangle other) {
    return (
        (other.x - x).abs() == overlap &&
        (other.y - y).abs() == overlap);
  }

  bool equals(Rectangle other) {
    return (
        x == other.x &&
        y == other.y &&
        width == other.width &&
        height == other.height);
  }

  bool equalsCenter(Rectangle other) {
    return (
        (x - other.x).abs() == other.width / 2 &&
        (y - other.y).abs() == other.height / 2);
  }

  Rectangle unionWith(Rectangle other) {
    return other.bounds.overlaps(this)
        ? this.union
        : other;
  }

  Rectangle intersectionWith(Rectangle other) {
    return other.bounds.overlaps(this)
        ? this.bounds.intersection
        : Rectangle.centered(
            x: other.x + other.width,
            y: other.y + other.height,
            width: this.width - (other.x - x),
            height: this.height - (other.y - y),
          );
  }

  Rectangle shift(double dx, double dy) {
    return Rectangle.centered(x + dx, y + dy, width, height);
  }

  Rectangle scale(double sx, double sy) {
    return Rectangle.centered(
        x, y, sx * width, sy * height);
  }

  Rectangle rotate90() {
    return Rectangle.centered(
        y, x + width, height, width);
  }

  Rectangle rotate180() {
    return Rectangle.centered(
        -x - width, -y - height, width, height);
  }

  Rectangle rotate270() {
    return Rectangle.centered(
        width - x, y + height, width, height);
  }

  Rectangle translate(double dx, double dy) {
    return Rectangle.centered(x + dx, y + dy, width, height);
  }

  Rectangle mirrorAbout(double axis) {
    return Rectangle.centered(
        x + (axis < x ? -axis : axis) - width,
        y + (axis < y ? -axis : axis) - height,
        width,
        height);
  }

  Rectangle mirrorAboutX() {
    return Rectangle.centered(
        x + (width - 2 * x) - width,
        y,
        width,
        height);
  }

  Rectangle mirrorAboutY() {
    return Rectangle.centered(
        x,
        y + (height - 2 * y) - height,
        width,
        height);
  }

  Rectangle mirrored() {
    return Rectangle.centered(
        x + (width - 2 * x) - width,
        y + (height - 2 * y) - height,
        width,
        height);
  }

  Rectangle translateAndScale(double dx, double dy, double sx, double sy) {
    return Rectangle.centered(
        x + dx,
        y + dy,
        sx * width,
        sy * height);
  }

  Rectangle translateAndRotate(double dx, double dy, double degrees) {
    final center = this.center;
    final half = this.half;
    final origin = Point(center.x, center.y);
    final origin2 = origin + Point(0, degrees);
    final origin3 = origin + Point(degrees, 0);

    final origin4 = origin + Point(degrees, -degrees);

    return Rectangle.centered(
      x: origin.x + dx,
      y: origin.y + dy,
      width: half.x,
      height: half.y,
    );
  }

  Rectangle rotated90() {
    return Rectangle.centered(
        y,
        x + width,
        height,
        width);
  }

  Rectangle rotated180() {
    return Rectangle.centered(
        -x - width,
        -y - height,
        width,
        height);
  }

  Rectangle rotated270() {
    return Rectangle.centered(
        width - x,
        y + height,
        width,
        height);
  }

  Rectangle shifted(double dx, double dy) {
    return Rectangle.centered(x + dx, y + dy, width, height);
  }

  Rectangle scaled(double sx, double sy) {
    return Rectangle.centered(x, y, sx * width, sy * height);
  }

  Rectangle scaledBy(double sx, double sy) {
    return Rectangle.centered(
        x,
        y,
        sx * width,
        sy * height);
  }

  Rectangle mirroredAboutX() {
    return Rectangle.centered(
        x + (width - 2 * x) - width,
        y,
        width,
        height);
  }

  Rectangle mirroredAboutY() {
    return Rectangle.centered(
        x,
        y + (height - 2 * y) - height,
        width,
        height);
  }

  Rectangle mirrored() {
    return Rectangle.centered(
        x + (width - 2 * x) - width,
        y + (height - 2 * y) - height,
        width,
        height);
  }

  @override
  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width, halfHeight: $height)';
}

