@pragma('vm:never-inline')
@pragma('vm:entry-point')

String fn0(List<int> readings, int target, int maxGap) {
  if (readings.isEmpty) return "No readings";
  int low = 0;
  int high = readings.length - 1;
  int result = -1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    if (readings[mid] == target) {
      result = mid;
      high = mid - 1;
    } else if (readings[mid] < target) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  if (result == -1) return "No readings";
  if (maxGap <= 0) return "Day ${result + 1}cm";
  int count = 0;
  int curr = result;
  for (int i = 0; i < readings.length; i++) {
    if (readings[i] == target) {
      if (count >= maxGap) {
        return "Day ${curr + 1}cm";
      }
      count = 0;
      curr = i;
    } else {
      count++;
    }
  }
  return "Day ${curr + 1}cm";
}

