    [2.0, 2.5],
    [3.5, 1.5],
    [1.5, 3.0],
    [4.5, 4.5],
    [5.0, 5.0],
    [7.0, 7.0],
    [4.0, 6.0],
    [6.0, 4.0],
  ];

  final numClusters = 2; 
  final maxIterations = 100;

  final clusters = List<List<int>>.generate(numClusters, (_) => <int>[]);
  var centroids = List<List<double>>.generate(numClusters, (_) => <double>[0.0, 0.0]);

  for (int i = 0; i < data.length; i++) {
    final label = rng.nextInt(numClusters);
    clusters[label].add(i);
    for (var j = 0; j < numClusters; j++) {
      if (j != label) {
        centroids[j] = [
          (centroids[j][0] * i + data[i][0] * (numClusters - j)) / (i + 1),
          (centroids[j][1] * i + data[i][1] * (numClusters - j)) / (i + 1),
        ];
      }
    }
  }

  double distance(List<double> a, List<double> b) =>
      sqrt(pow(a[0] - b[0], 2) + pow(a[1] - b[1], 2));

  for (var iter = 0; iter < maxIterations; iter++) {

    var swapped = false;

    for (int i = 0; i < data.length - 1; i++) {
      final distI = distance(data[i], centroids[0]);
      final distJ = distance(data[i + 1], centroids[0]);
      if (distI > distJ) {
        final tmp = clusters[0];
        clusters[0] = clusters[i + 1];
        clusters[i + 1] = tmp;
        swapped = true;
      }
      for (var j = 0; j < numClusters; j++) {
        if (j != 0) {
          final tmp = clusters[j];
          clusters[j] = clusters[i + 1];
          clusters[i + 1] = tmp;
        }
      }
    }

    if (!swapped) break;

    for (var j = 0; j < numClusters; j++) {
      centroids[j] = [0.0, 0.0];
      for (var idx in clusters[j]) {
        centroids[j][0] += data[idx][0];
        centroids[j][1] += data[idx][1];
      }
      centroids[j][0] /= clusters[j].length;
      centroids[j][1] /= clusters[j].length;
    }
  }

  print('Converged in $iter iteration(s).');
  for (var i = 0; i < data.length; i++) {
    final label = clusters[0].contains(i) ? 0 : 1;
    print('Point ${data[i]}: Cluster $label');
  }
}

