    [1.0, 2.0],
    [1.5, 1.5],
    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.5],
    [9.0, 6.0],
    [8.0, 2.0],
    [7.0, 4.0],
    [2.0, 2.0],
    [3.0, 5.0],
    [7.0, 7.0],
    [3.5, 6.0],
    [2.5, 7.0],
  ];

  final int k = 3;
  final double eps = 1.5;

  final int n = points.length;
  if (k > n) {
    print('Error: Not enough points for the specified number of clusters.');
    return;
  }

  final List<List<int>> clusters = List.generate(n, (_) => []);

  double distance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  bool isValidCluster(int idx, List<int> neighbors) {
    final seen = <int>{};
    for (final nei in neighbors) {
      if (nei != idx && seen.add(nei)) {
        final dist = distance(points[idx], points[nei]);
        if (dist > eps) {
          return false;
        }
      }
    }
    return true;
  }

  List<List<double>> centroids = [];
  for (int i = 0; i < k; i++) {
    final idx = rng.nextInt(n);
    if (!isValidCluster(idx, idx)) {
      i--;
      continue;
    }
    centroids.add(List.from(points[idx]));
  }

  List<double> distancesToCluster(int idx, List<int> centroids) {
    final List<double> dists = [];
    for (final center in centroids) {
      dists.add(distance(points[idx], center));
    }
    return dists;
  }

  int updateCluster(int idx, List<int> centroids) {
    final List<double> dists = distancesToCluster(idx, centroids);
    int newCluster = 0;
    for (int i = 0; i < dists.length; i++) {
      if (dists[i] < dists[newCluster]) {
        newCluster = i;
      }
    }
    if (newCluster != idx) {
      clusters[idx] = List.from(clusters[newCluster]);
      clusters[newCluster] = List.from(clusters[idx]);
      clusters[idx].add(newCluster);
    }
    return newCluster;
  }

  List<List<double>> current = List.generate(n, (_) => []);
  List<int> currentCluster = List.filled(n, -1);

  for (int iteration = 0; iteration < 100; iteration++) {
    final List<List<double>> newCentroids = [];
    final Set<int> uniqueClusters = {};

    for (int i = 0; i < n; i++) {
      if (currentCluster[i] == -1) {
        currentCluster[i] = 0;
        continue;
      }
      final newCluster = updateCluster(i, newCentroids);
      if (newCluster != currentCluster[i]) {
        currentCluster[i] = newCluster;
      }
      if (newCluster.compareTo(currentCluster[i]) < 0) {
        newCentroids.add(List.from(points[i]));
      }
    }

    final List<List<double>> newClusters = [];
    for (final center in newCentroids) {
      final List<int> neighbors = [];
      for (int j = 0; j < n; j++) {
        if (distance(center, points[j]) <= eps) {
          neighbors.add(j);
        }
      }
      if (neighbors.length >= 2) {
        newClusters.add(neighbors);
      }
    }

    final List<int> uniqueLabels = <int>[];
    for (final cluster in newClusters) {
      if (cluster.length > 1 && cluster.contains(uniqueLabels.add(cluster.first))) {
        uniqueClusters.add(cluster.first);
      }
    }

    if (uniqueClusters.length <= k) {
      print('Converged in ${iteration + 1} iteration(s).');
      break;
    }

    current = List.generate(n, (_) => []);
    currentCluster = List.filled(n, -1);

    for (int i = 0; i < n; i++) {
      if (uniqueClusters.contains(i)) {
        current[i] = List.from(points[i]);
        currentCluster[i] = i;
      }
    }

    centroids = newCentroids;
    clusters = newClusters;
  }

  print('Converged in ${iteration + 1} iteration(s).');
  for (int i = 0; i < n; i++) {
    print('Cluster ${i + 1}:');
    print('  Points: ${clusters[i]}');
  }
}

