    [8.0, 2.0],
    [7.0, 4.0],
    [2.0, 2.0],
    [3.0, 4.5],
  ];

  const double epsil = 0.5;
  const int minPts = 2;
  const int maxIterations = 50;

  final random = Random(0);

  final int n = data.length;
  if (n == 0) {
    print('No points provided.');
    return;
  }

  List<List<double>> clusters = List.generate(n, (_) => []);

  for (int i = 0; i < n; i++) {
    clusters[i].add(data[i]);
  }

  bool hasConverged = false;
  int iteration = 0;

  while (!hasConverged && iteration < maxIterations) {
    hasConverged = true;
    iteration++;

    for (int i = 0; i < n; i++) {
      if (clusters[i].length >= minPts) continue;

      final neighbors = <int>[];
      for (int j = 0; j < n; j++) {
        if (distance(data[i], data[j]) <= epsil) {
          neighbors.add(j);
        }
      }

      if (neighbors.length < minPts) continue;

      final newCluster = <int>[];
      for (final point in clusters[i]) {
        for (final neighbor in neighbors) {
          if (point == neighbor) continue;
          if (distance(point, neighbor) > epsil) continue;
          newCluster.add(neighbor);
        }
      }

      clusters[i] = List<int>.from(newCluster);
    }

    for (int cluster in clusters) {
      if (cluster.length >= minPts) continue;
      for (int i = 0; i < n; i++) {
        if (clusters[i].contains(cluster)) {
          clusters[i].remove(cluster);
        }
      }
    }

    final Set<int> uniqueClusters = {};
    for (final cluster in clusters) {
      if (cluster.isNotEmpty) {
        uniqueClusters.add(cluster);
      }
    }

    clusters = uniqueClusters.toList();

    for (int clusterIndex = 0; clusterIndex < clusters.length; clusterIndex++) {
      final cluster = clusters[clusterIndex];
      if (cluster.isEmpty) continue;

      final centroid = data
          .where((point) => cluster.contains(point))
          .reduce((a, b) => (a[0] + b[0]) / 2, keepIfEven: false);

      clusters[clusterIndex] = [centroid];

      for (final point in cluster) {
        for (final neighbor in clusters) {
          if (!neighbor.contains(point)) continue;
          if (distance(point, neighbor[0]) > epsil) continue;
          neighbor.add(point);
        }
      }
    }
  }

  print('Converged in $iteration iteration(s).');
  for (int i = 0; i < clusters.length; i++) {
    print('Cluster $i:');
    for (final point in clusters[i]) {
      print('  Point: $point');
    }
