    [1.0, 0.5],
    [9.0, 11.0],
    [8.0, 7.0],
    [4.5, 7.0],
    [3.5, 6.0],
    [2.0, 2.5],
  ];

  final int k = 3;
  final double eps = 0.5;
  final int maxIterations = 100;

  final int n = data.length;
  final List<List<double>> centroids = List.generate(k, (_) => List.filled(data[0].length, 0.0));

  double dist(List<double> a, List<double> b) {
    double sum = 0.0;
    for (var i = 0; i < a.length; i++) {
      sum += pow(a[i] - b[i], 2);
    }
    return sqrt(sum);
  }

  for (var iter = 0; iter < maxIterations; iter++) {

    final List<List<double>> pointsInCurrent = [];
    for (var i = 0; i < n; i++) {

      final double minDist = double.infinity;
      var currentCluster = -1;

      for (var c = 0; c < k; c++) {
        final double distToC = dist(data[i], centroids[c]);
        if (distToC < minDist) {
          minDist = distToC;
          currentCluster = c;
        }
      }
      pointsInCurrent.add(List.from(data[i]));

      if (currentCluster != -1) {
        for (var c = 0; c < k; c++) {
          if (c == currentCluster) continue;
          final double distToC = dist(data[i], centroids[c]);
          if (distToC < eps) {
            eps = distToC;
          }
        }
      }
    }

    final Set<int> newClusterCenters = {};
    for (var i = 0; i < pointsInCurrent.length; i++) {
      for (var j = i + 1; j < pointsInCurrent.length; j++) {
        final double oldDist = dist(pointsInCurrent[i], pointsInCurrent[j]);
        if (oldDist < eps) continue;

        final List<double> newCentroid = [];
        for (var d = 0; d < pointsInCurrent[i].length; d++) {
          newCentroid.add(pointsInCurrent[i][d] + pointsInCurrent[j][d] / 2.0);
        }

        for (var c = 0; c < k; c++) {
          if (dist(newCentroid, centroids[c]) < eps) {
            newClusterCenters.add(c);
            break;
          }
        }
      }
    }

    for (final c in newClusterCenters) {
      centroids[c] = pointsInCurrent[rng.nextInt(pointsInCurrent.length)];
    }

    final List<double> distances = List.filled(n, double.infinity);
    for (var i = 0; i < n; i++) {
      for (var c = 0; c < k; c++) {
        final double dist = dist(data[i], centroids[c]);
        if (dist < distances[i]) {
          distances[i] = dist;
        }
      }
    }

    final double newAvg = 0.0;
    for (var d in distances) {
      if (d != double.infinity) {
        newAvg += d;
      }
    }
    newAvg /= n;

    final List<List<double>> pointsInNext = [];
    for (var i = 0; i < n; i++) {
      if (distances[i] <= newAvg) {
        pointsInNext.add(List.from(data[i]));
      }
    }

    if (pointsInNext.length == k) {
      break;
    }

    centroids.clear();
    centroids = List.generate(k, (_) => List.filled(pointsInNext[0].length, 0.0));

    for (var i = 0; i < pointsInNext.length; i++) {
      for (var j = 0; j < pointsInNext[i].length; j++) {
        for (var c = 0; c < k; c++) {
          centroids[c][j] += pointsInNext[i][j];
        }
      }
    }

    for (var c = 0; c < k; c++) {
      for (var j = 0; j < pointsInNext[0].length; j++) {
        centroids[c][j] /= pointsInNext.length;
      }
    }
  }

  print('Converged in $iter iteration(s).');
  for (var c = 0; c < k; c++) {
    print('Cluster $c:');
    for (var i = 0; i < data.length; i++) {
      if (distances[i] <= eps) {
        print('  Points: ${data[i]}');
      }
    }
    print(' centroid: ${centroids[c]}');
  }
}

