  int a = p0[0], b = p1[0], n = p0[1], m = p1[1];
  while (b != 0) {
    int t = b;
    b = a % b;
    a = t;
  }
  return (a + n * m) % 1000;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')

int fn0(List<int> packetSizes, List<int> delays) {
  int sum = 0;
  for (int i = 0; i < packetSizes.length; i++) {
    int size = packetSizes[i];
    int d = delays[i];
    if (size > 0 && d > 0) {
      int a = size;
      int b = d;
      while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
      }
      sum += a;
    }
  }
  return sum;
}

